-- WhatsNew.lua: generated from CHANGELOG.md by the release (make_whatsnew.py; do not edit by hand).
-- Per version: v, date, items = { { s = "add"|"chg"|"fix", fr = { title, text }, en = { title, text } } }
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.124", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, les portails du mage", "Un portail que tu sais ouvrir (Orgrimmar, Fossoyeuse, Les Pitons-du-Tonnerre ; Hurlevent, Forgefer, Darnassus côté Alliance) compte comme une téléportation quand tu as une Rune des portails : ouvre-le et prends-le. La flèche le lance comme une téléportation." }, en = { "GPS", "A mage's own portals count as teleports when a Rune of Portals is in the bags." } },
    { s = "add", fr = { "GPS, la rune qui manque", "Quand tu connais une téléportation ou un portail mais n'as pas la rune, le trajet s'en passe ; la carte du guide dit maintenant ce qu'elle ferait gagner (« Avec une Rune de téléportation : Téléport : Fossoyeuse (~8 min de moins) »). Avant, la téléportation disparaissait sans un mot." }, en = { "GPS", "When a missing rune leaves a teleport out, the card says how much time it would save." } },
  } },
  { v = "1.0.0-beta.123", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, envoyer les destinations à Shortest Path", "Si Shortest Path Forever est installé, Réglages > GPS > « Envoyer les destinations à Shortest Path ». Les étapes du guide, les repères de la carte (livres de Naowh, Ctrl-clic) et /way passent alors par lui : son trajet tracé sur la carte, les vols, les bateaux et zeppelins avec le compte à rebours du départ, les portails, et sa flèche. La flèche de WL Helper et son chemin se cachent pendant ce temps. Éteint par défaut ; si Shortest Path ne peut pas prendre le point (encore en chargement), le GPS de WL Helper guide." }, en = { "GPS", "Send destinations to Shortest Path Forever (its map route, flights, boats with departure timers), Settings > GPS." } },
  } },
  { v = "1.0.0-beta.122", date = "2026-11-18", items = {
    { s = "chg", fr = { "Petit suivi lisible", "Le bouton « − » du guide passe au petit suivi (l'action en cours, ses objectifs avec leur barre, les deux actions suivantes) à la place de la ligne unique d'avant. Textes plus grands (action en 14, objectifs en 13) et cadre un peu plus large. Clic sur le suivi : le guide complet revient." }, en = { "The guide's \"−\" switches to the small tracker (bigger text, objective bars); click it to get the whole guide back.", "" } },
    { s = "fix", fr = { "Classement PvP de la guilde, les doublons", "Chaque membre n'apparaît plus qu'une fois. Sur Forever, un personnage a un nom de famille (« Alandir Sheeplover ») : les anciennes copies le gardaient sous le prénom seul, les nouvelles sous le prénom et le nom, et ta propre ligne restait sous ton prénom. Les deux sont fusionnées (les chiffres les plus récents gardés) ; deux membres du même prénom restent séparés." }, en = { "Guild PvP ranking", "No more members listed twice (Forever surnames)." } },
    { s = "fix", fr = { "GPS, dans la zone d'un objectif", "Quand tu es déjà dans la zone pointillée, près des mobs (moins de 40 mètres), la flèche ne t'envoie plus au bord de la zone : le point, c'est toi, et il te suit. Loin de tout mob (une île au milieu de la zone) ou hors de la zone, elle t'emmène au mob le plus proche, comme avant." }, en = { "GPS", "Inside an objective's area, the arrow no longer sends you to its edge." } },
  } },
  { v = "1.0.0-beta.121", date = "2026-11-18", items = {
    { s = "chg", fr = { "Guide, la route suit ta position", "Toutes les 5 secondes, si tu es à plus de 400 mètres de l'endroit d'où la route a été calculée, les étapes restantes sont remises dans l'ordre depuis là où tu es (toujours en respectant l'ordre obligatoire des quêtes, puis le chemin le plus court). Ça couvre la pierre de foyer, un portail, un bateau ou une longue course dans la même zone, qui ne déclenchaient rien. Pas en combat, pas en vol, pas en donjon ; pas à chaque pas, pour que la flèche ne saute pas d'une étape à l'autre." }, en = { "The guide re-orders the steps left from where you are once you are 400 yards from where the route was planned (hearthstone, portal, boat, long ride).", "" } },
  } },
  { v = "1.0.0-beta.120", date = "2026-11-18", items = {
    { s = "fix", fr = { "Guide, après un vol", "Le guide remet les étapes dans l'ordre à l'atterrissage. Avant, une route calculée au départ (par exemple à Camp Mojache en Féralas, en prenant « The Sunken Temple ») restait telle quelle après le vol : arrivé à Gadgetzan, le GPS t'envoyait chez Larion à Un'Goro au lieu de te faire rendre la quête à Marvon, tout près." }, en = { "The guide re-orders its steps when a flight lands (a route planned in Feralas no longer sends you to Un'Goro past Marvon's turn-in).", "" } },
    { s = "add", fr = { "Chaîne d'Anthion côté Alliance", "Les quêtes de Deliana à Forgefer (An Earnest Proposition, A Supernatural Device, Return to Deliana, Just Compensation, In Search of Anthion, Anthion's Parting Words, Bodley's Unfortunate Fate), une par classe dont le paladin, lues sur Wowhead Forever. La version Alliance demande 15 Winterspring Blood Sample (Frostsaber de Berceau-de-l'Hiver), pas le venin de Silithus. Les quêtes communes (The Challenge, Dead Man's Plea, les morceaux d'amulette de Valthalak) s'ouvrent maintenant aussi pour l'Alliance, avec la version de ta faction et de ta classe." }, en = { "The Alliance Anthion chain (Deliana, Ironforge), every class including paladin; the shared Valthalak quests now open for the Alliance.", "" } },
  } },
  { v = "1.0.0-beta.119", date = "2026-11-18", items = {
    { s = "chg", fr = { "Trouver un groupe, résultats plus lisibles", "Chaque ligne est plus haute, le nom plus grand, et les détails (niveau ou places, donjon, zone, depuis quand) juste en dessous dans une taille lisible, au lieu d'une petite colonne au milieu. Les rôles s'affichent en 5 grosses icônes : pour un groupe, une par place (tank, soigneur, 3 dégâts), allumée si elle est prise, pâle si elle est libre, comme dans LFG Forever ; pour un joueur, les rôles qu'il propose." }, en = { "Find a group", "Taller rows, bigger names, details under them, and 5 big role slots (taken bright, free faint)." } },
  } },
  { v = "1.0.0-beta.118", date = "2026-11-18", items = {
    { s = "add", fr = { "GPS, repères de la carte", "Un repère posé sur la carte du monde lance le GPS de WL Helper jusque-là (flèche et chemin à pied), qu'il soit posé par toi (Ctrl-clic) ou par un autre addon qui pose le repère du jeu, comme les livres, coffres et rares de Naowh Forever (« Click for a waypoint »). Repère enlevé : le GPS s'arrête. Jamais les repères que WL Helper pose lui-même, rien en donjon. Réglages > GPS > « Suivre les repères de la carte » pour l'éteindre." }, en = { "GPS follows map pins (yours or another addon's, like Naowh's books); Settings > GPS to turn it off.", "" } },
  } },
  { v = "1.0.0-beta.117", date = "2026-11-18", items = {
    { s = "fix", fr = { "Guide, étapes de boss", "Une étape de boss dont toutes les quêtes sont rendues compte comme faite, même si le guide n'a pas vu le boss mourir (tué avant un /reload ou une déconnexion). Avant, l'onglet « Dans le donjon » pouvait rester à 8 sur 9 alors que tout était fait (Prison d'Alcaz, Tidemistress Ca'zass)." }, en = { "Boss steps whose quests are all turned in count as done, even without a kill seen this session.", "" } },
  } },
  { v = "1.0.0-beta.116", date = "2026-11-18", items = {
    { s = "add", fr = { "Meilleur pour toi", "Tape « /wlh bis » (ou « /wlh bis 60 » pour un autre niveau). Pour chaque emplacement, les 3 meilleures pièces que tu peux porter, classées par WL Helper Gear pour ta spé avec tes vraies stats, tes talents et tes plafonds de toucher ; le gain sur ce que tu portes, et d'où vient la pièce (donjon et boss, quête, métier, réputation ; les pièces PvP renvoient à « /wlh pvp »). Les raids sont laissés de côté tant qu'ils ne sont pas ouverts. La liste est calculée, pas recopiée d'un guide : Forever a changé beaucoup d'objets." }, en = { "Best for you (/wlh bis [level])", "The top 3 pieces per slot for your spec, computed by WL Helper Gear, with the gain and the source." } },
  } },
  { v = "1.0.0-beta.115", date = "2026-11-18", items = {
    { s = "fix", fr = { "XP des quêtes", "128 quêtes affichaient l'XP de base, sans le bonus de Forever (souvent x1,75 à x2,7). Elles ont maintenant l'XP réelle, celle de Wowhead Forever, la même qu'en jeu (Blood Red Bandanas : 9 700 XP). Les totaux d'XP du guide et de la vue d'ensemble sont donc bien plus justes." }, en = { "Quest XP", "128 quests showed the base XP without Forever's bonus; they now show the real XP (Wowhead Forever, as in game)." } },
    { s = "fix", fr = { "Quêtes ajoutées", "An Ambassador of Evil (Alliance, Ironforge, avant The Lost Tablets of Will à Uldaman) et Elven Legends côté Alliance (Scholar Runethorn, Feathermoon) ; les librams de Hache-tripes s'ouvrent maintenant aussi à l'Alliance." }, en = { "Added An Ambassador of Evil and the Alliance Elven Legends (Dire Maul librams open to the Alliance).", "" } },
  } },
  { v = "1.0.0-beta.114", date = "2026-11-17", items = {
    { s = "add", fr = { "Guide PvP", "Tape « /wlh pvp ». Pour ta classe, chaque pièce du set PvP bleu « Premier » (niveau d'objet 60, dès le niveau 55) avec son prix en honneur et en marques, ce qu'il te manque d'après ton honneur et tes marques, le total pour le set, et le champ de bataille à faire en premier (celui dont il te manque le plus de marques). Quand une classe a plusieurs sets (druide, chaman, prêtre, paladin), WL Helper Gear choisit le meilleur pour ta spé et nomme les autres. Puis la quête Field of Honor (Wizzik Dustfizz à Gadgetzan) et les sceaux « Emboldened » qui rendent une pièce épique plus tard. Prix lus sur Wowhead Forever (vendeur Lady Palanseer) : tête 9 000 honneur + 15 marques d'Alterac, torse 9 350 + 15 Arathi, jambes 9 000 + 15 Goulet, épaules 6 350 + 10 Arathi, mains 7 500 + 10 Goulet, pieds 7 500 + 10 Îles Darkspear, taille 6 000 + 10 Arathi, poignets 4 500 + 10 Goulet." }, en = { "PvP guide (/wlh pvp)", "The rare PvP set for your class, its Forever prices (Wowhead), what you still miss, which battleground first, Field of Honor." } },
  } },
  { v = "1.0.0-beta.113", date = "2026-11-17", items = {
    { s = "add", fr = { "Trouver un groupe, raccourci clavier", "« Ouvrir Trouver un groupe » dans Échap > Options > Raccourcis > AddOns > WL Helper." }, en = { "Find a group", "A key binding." } },
    { s = "add", fr = { "Trouver un groupe, joueurs qui quittent", "Clic droit sur un nom > « A quitté un donjon en cours ». La marque se cumule ; elle s'affiche dans la bulle du joueur dans les résultats, et une ligne dans le chat te prévient quand il rejoint ton groupe. Le jeu cache les noms en donjon, donc l'addon ne devine jamais qui est parti : c'est toi qui marques." }, en = { "Find a group", "Mark players who left a dungeon mid-run (by hand; names are hidden in instances)." } },
    { s = "fix", fr = { "Prérequis par classe", "Quand une quête demande « la version de ta classe » d'une autre (An Earnest Proposition, Just Compensation, Anthion's Parting Words), seule celle de ta classe compte. Avant, ces quêtes restaient fermées pour tout le monde. A Supernatural Device, In Search of Anthion et Bodley's Unfortunate Fate ont leurs prérequis de Wowhead Forever." }, en = { "Class-variant prerequisites", "Only your class's version counts (Anthion and Valthalak chains open again)." } },
  } },
  { v = "1.0.0-beta.112", date = "2026-11-17", items = {
    { s = "chg", fr = { "Améliorations, « Presque pareil »", "Seulement sous 10 %. À partir de 10 %, le pourcentage reste affiché en vert ou en rouge (« +12 % » est une vraie amélioration), avec en dessous l'écart réel en points (« Écart réel : ~2 de puissance des sorts seulement. »)." }, en = { "Upgrades", "\"About the same\" only under 10 %; from 10 % the percent stays, with the real gap in points under it." } },
  } },
  { v = "1.0.0-beta.111", date = "2026-11-17", items = {
    { s = "fix", fr = { "Quêtes du guide vérifiées sur Wowhead Forever", "Les 526 quêtes du guide ont été lues une à une sur Wowhead Forever et comparées à nos données. 82 corrections :" }, en = { "", "" } },
    { s = "fix", fr = { "", "faction : 14 quêtes réservées à la Horde ou à l'Alliance étaient données pour les deux (ou l'inverse, comme Da Voodoo) ;" }, en = { "", "" } },
    { s = "fix", fr = { "", "niveau et niveau requis : 17 quêtes (Ruines de Lordaeron, Horn of Xelthos, Blood Red Bandanas...) ;" }, en = { "", "" } },
    { s = "fix", fr = { "", "partage en groupe : 36 quêtes ;" }, en = { "", "" } },
    { s = "fix", fr = { "", "noms de Forever : The Great Ezra Grimm (au lieu de Fras Siabi), Pip Quickwit (au lieu de Finkle Einhorn), Velarok Windblade, Scarshield Infiltrator, The Eastern Kingdoms, Connery's Trunk ;" }, en = { "", "" } },
    { s = "fix", fr = { "", "qui donne la quête : The Key to Scholomance (Apothecary Dithers), Heed My Call (Rau Cliffrunner, Freewind Post) ;" }, en = { "", "" } },
    { s = "fix", fr = { "", "prérequis : The Stone Circle, Grark Lorkrub, Lord Banehollow." }, en = { "All 526 guide quests checked page by page on Wowhead Forever: 82 fixes (factions, levels, sharing, Forever names, givers, prerequisites).", "" } },
  } },
  { v = "1.0.0-beta.110", date = "2026-11-17", items = {
    { s = "chg", fr = { "Choisir un guide", "Un clic sur une carte ouvre la vue d'ensemble de ce donjon, et « Lancer le guide » y remplace le guide en cours. Pour enchaîner plusieurs donjons en une seule route, coche la case de chaque carte puis « Combiner les N guides » en bas. Le guide en cours n'est plus coché d'office : sa carte a un contour vert et sa bulle dit « Guide en cours »." }, en = { "Pick a guide", "Click a card to open it alone; tick boxes to combine several." } },
    { s = "fix", fr = { "Améliorations (WL Helper Gear), le toucher", "Le toucher de l'objet porté n'est plus compté deux fois. Avant, échanger deux colliers pouvait donner +46 % dans un sens et -1 % dans l'autre ; les deux pièces sont maintenant jugées depuis ton toucher sans l'une ni l'autre." }, en = { "Gear", "The worn piece's hit no longer skews the comparison (same swap, same verdict both ways)." } },
    { s = "fix", fr = { "Prison d'Alcaz, « More Valuable Than Gold »", "Plus d'étape « Faire » dans le donjon ; le trésor de Mason se trouve sous le plancher de l'auberge de Moonbrook, l'étape « Rendre » y mène." }, en = { "Alcaz Prison", "No inside \"do\" step for Mason's treasure." } },
  } },
}
